import json
from src.nodes.base import BaseNode
from src.runtime import houdini_runtime

class HouMCPBuildNodeChainNode(BaseNode):
    name = "Houdini MCP: Build Node Chain"
    category = "Houdini"

    def __init__(self):
        super().__init__()
        self.icon_path = "icons/houdini_icon.png"
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("spec_json", "string", widget_type="text", default="{\n  \"intent\": \"\",\n  \"nodes\": [],\n  \"connections\": [],\n  \"layout\": true,\n  \"cook\": false\n}")
        self.add_input("intent", "string", widget_type="text", default="")
        self.add_output("ok", "bool")
        self.add_output("created_paths", "list")
        self.add_output("id_to_path", "any")
        self.add_output("error", "string")
        self.add_output("intent", "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw_spec = inputs.get("spec_json") or ""
        override_intent = (inputs.get("intent") or "").strip()

        if isinstance(raw_spec, dict):
            spec = raw_spec
        else:
            try:
                spec = json.loads(raw_spec) if raw_spec.strip() else {}
            except json.JSONDecodeError as exc:
                self.log_error(f"spec_json is not valid JSON: {exc}")
                return {"ok": False, "created_paths": [], "id_to_path": {}, "error": f"invalid spec_json: {exc}", "intent": override_intent, "exec_out": True}

        if not isinstance(spec, dict):
            self.log_error("spec_json must decode to a JSON object.")
            return {"ok": False, "created_paths": [], "id_to_path": {}, "error": "spec must be an object", "intent": override_intent, "exec_out": True}

        if override_intent:
            spec = dict(spec)
            spec["intent"] = override_intent

        try:
            result = await houdini_runtime.build_node_chain(spec)
        except Exception as exc:
            self.log_error(f"build_node_chain raised: {exc}")
            return {"ok": False, "created_paths": [], "id_to_path": {}, "error": str(exc), "intent": override_intent or str(spec.get("intent") or ""), "exec_out": True}

        if result.get("ok"):
            self.log_success(
                f"build_node_chain '{result.get('intent') or 'unnamed'}': "
                f"created {len(result.get('created_paths') or [])} node(s)."
            )
        else:
            self.log_error(f"build_node_chain failed: {result.get('error')}")

        return {
            "ok": bool(result.get("ok")),
            "created_paths": list(result.get("created_paths") or []),
            "id_to_path": dict(result.get("id_to_path") or {}),
            "error": result.get("error") or "",
            "intent": result.get("intent") or "",
            "exec_out": True,
        }

def register_node():
    return HouMCPBuildNodeChainNode
